mapper.select:
select  

     and (e.title like concat('%', #{q}, '%') or e.vendor like concat('%', #{q}, '%') or e.receipt_no like concat('%', #{q}, '%')) 
     and e.status = #{status} 
     and e.category_id = #{categoryId} 
     and e.spent_on >= #{from} 
     and e.spent_on <= #{to} 

order by e.spent_on desc, e.id desc

select currency, sum(amount) as total, count(*) as count
from nad_expense
where status in ('APPROVED', 'PAID')
 and spent_on >= #{from} 
 and spent_on <= #{to} 
group by currency

mapper.insert:
insert into nad_expense_category (code, name, sort_order, active)
values (#{code}, #{name}, coalesce((select s.m from (select max(sort_order) + 1 as m
        from nad_expense_category) s), 100), 1)
